void dfs(int u) {
    if (u > n) { /* 输出 */ return; }
    for (int i = 1; i <= n; i++) {
        if (!used[i]) {
            Path[u] = i; used[i] = true;
            dfs(u + 1);
            used[i] = false;  // 回溯撤销标记
        }
    }
}

