void qs(int q[], int l, int r) {
    if (l >= r) return;
    int i = l - 1, j = r + 1, x = q[(l + r) >> 1];
    while (i < j) {
        do i++; while (q[i] < x);
        do j--; while (q[j] > x);
        if (i < j) swap(q[i], q[j]);
    }
    qs(q, l, j);
    qs(q, j + 1, r);  // 以j为界递归处理左右两部分
}

int quick_select(int q[], int l, int r, int k) {
    if (l == r) return q[l];
    int i = l - 1, j = r + 1, x = q[(l + r) >> 1];
    while (i < j) {
        do i++; while (q[i] < x);
        do j--; while (q[j] > x);
        if (i < j) swap(q[i], q[j]);
    }
    int left_len = j - l + 1;
    if (k <= left_len) return quick_select(q, l, j, k);  // 目标在左半
    else return quick_select(q, j + 1, r, k - left_len);
}

